def on_cast(ctx, caster, target):
    caster_entity = ctx.entity(caster)
    if caster_entity is None:
        return

    victim = ctx.entity_at(target)
    if victim is None:
        ctx.log("The lightning finds nothing to strike.")
        return

    damages = [4, 2, 1]
    hit_ids = set()
    current_pos = target

    for i, damage in enumerate(damages):
        victim = ctx.entity_at(current_pos)
        if victim is None or victim.id in hit_ids:
            break

        if victim.faction == caster_entity.faction:
            break

        ctx.damage(victim.id, damage, source=caster)
        hit_ids.add(victim.id)

        if i < len(damages) - 1:
            next_target = None
            best_distance = float('inf')
            for other in ctx.entities(faction='enemy'):
                if other.id not in hit_ids:
                    dist = current_pos.distance_to(other.pos)
                    if dist < best_distance:
                        best_distance = dist
                        next_target = other

            if next_target is None:
                break
            current_pos = next_target.pos

    if len(hit_ids) == 0:
        ctx.log("The lightning finds nothing to strike.")


define_spell(
    id="chain_lightning",
    name="Chain Lightning",
    description="A bolt of electricity that jumps up to 3 enemies in succession, dealing 4 damage, then 2, then 1.",
    mana_cost=5,
    target="entity",
    range=7,
    on_cast=on_cast,
)
